+// Len returns the number of AST nodes recorded by the inspector.
+// It equals the number of non-nil nodes that [ast.Inspect] visits
+// over the files supplied to [New].
+func (in *Inspector) Len() int {
+	var n int
+	for i := int32(0); i < int32(len(in.events)); i++ {
+		if in.events[i].index > i {
+			n++
+		}
+	}
+	return n
+}
+
 // Preorder visits all the nodes of the files supplied to [New] in
 // depth-first order. It calls f(n) for each node n before it visits
 // n's children.
