+// TestLen verifies that Inspector.Len returns the same count
+// as ast.Inspect visits over the same files.
+func TestLen(t *testing.T) {
+	inspect := inspector.New(netFiles)
+
+	var count int
+	for _, f := range netFiles {
+		ast.Inspect(f, func(n ast.Node) bool {
+			if n != nil {
+				count++
+			}
+			return true
+		})
+	}
+
+	if got := inspect.Len(); got != count {
+		t.Errorf("Len() = %d, want %d", got, count)
+	}
+}
